function parseRSS(text, sourceName) {
  const jobs = [];
  if (!text || typeof text !== 'string') return jobs;
  const itemRegex = /<item>([\s\S]*?)<\/item>/gi;
  let match;
  while ((match = itemRegex.exec(text)) !== null) {
    const xml = match[1];
    const getTag = (tag) => {
      const m = xml.match(new RegExp('<' + tag + '[^>]*>([\\s\\S]*?)<\\/' + tag + '>', 'i'));
      return m ? m[1].replace(/<![CDATA[/g, '').replace(/]]>/g, '').replace(/<[^>]+>/g, '').trim() : '';
    };
    const title = getTag('title');
    const link = (getTag('link') || getTag('guid') || '').trim();
    if (!title || !link) continue;
    let jobTitle = title;
    let company = '';
    if (title.includes(' at ')) {
      const p = title.split(' at ');
      jobTitle = p[0].trim();
      company = p.slice(1).join(' at ').trim();
    }
    const desc = getTag('description').replace(/\s+/g, ' ').substring(0, 3000);
    const safeId = link.replace(/[^a-zA-Z0-9]/g, '').substring(0, 24);
    jobs.push({
      json: {
        job_id: sourceName.replace(/\s/g, '_') + '_' + safeId,
        job_title: jobTitle,
        company: company,
        job_url: link,
        source: sourceName,
        location_text: '',
        salary: '',
        description: desc,
        posted_date: getTag('pubDate'),
        tags: '',
        date_found: new Date().toISOString()
      }
    });
  }
  return jobs;
}
