// Wellfound does not expose a public API. This node attempts to parse job data
// from the HTML response. For full coverage, configure a Wellfound account
// with their Talent API or use Apify/ScrapingBee integration.
const html = ($input.first().json.data || '').toString();
const jobs = [];
// Try to find JSON-LD structured data
const ldRegex = /<script[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi;
let ldMatch;
while ((ldMatch = ldRegex.exec(html)) !== null) {
  try {
    const ld = JSON.parse(ldMatch[1]);
    const listings = Array.isArray(ld) ? ld : [ld];
    for (const item of listings) {
      if (item['@type'] !== 'JobPosting') continue;
      jobs.push({
        json: {
          job_id: 'wellfound_' + (item.identifier || '').toString().replace(/[^a-zA-Z0-9]/g, '').substring(0, 20),
          job_title: item.title || '',
          company: (item.hiringOrganization || {}).name || '',
          job_url: item.url || '',
          source: 'Wellfound',
          location_text: (item.jobLocation || {}).addressLocality || 'Remote',
          salary: item.baseSalary ? JSON.stringify(item.baseSalary) : '',
          description: (item.description || '').replace(/<[^>]+>/g, ' ').substring(0, 3000),
          posted_date: item.datePosted || '',
          tags: '',
          date_found: new Date().toISOString()
        }
      });
    }
  } catch (e) {}
}
return jobs.length > 0 ? jobs : [];

// YC Work at a Startup does not expose a public RSS or open API.
// This node attempts to extract structured data from their HTML.
// For reliable coverage, use the Otta API or Algolia endpoint they expose.
const html = ($input.first().json.data || '').toString();
const jobs = [];
// Try Algolia/next.js __NEXT_DATA__ embedded JSON
const nextDataMatch = html.match(/<script id="__NEXT_DATA__"[^>]*>([\s\S]*?)<\/script>/);
if (nextDataMatch) {
  try {
    const nextData = JSON.parse(nextDataMatch[1]);
    const pageProps = ((nextData.props || {}).pageProps || {});
    const jobList = pageProps.jobs || pageProps.jobPostings || [];
    for (const job of jobList) {
      if (!job || !job.title) continue;
      jobs.push({
        json: {
          job_id: 'yc_' + (job.id || job.slug || '').toString().replace(/[^a-zA-Z0-9]/g, '').substring(0, 20),
          job_title: job.title || '',
          company: (job.company || {}).name || job.companyName || '',
          job_url: job.url || ('https://www.workatastartup.com/jobs/' + (job.id || '')),
          source: 'YC Work at a Startup',
          location_text: job.locationTag || 'Remote',
          salary: job.salary || '',
          description: (job.description || '').replace(/<[^>]+>/g, ' ').substring(0, 3000),
          posted_date: job.createdAt || '',
          tags: Array.isArray(job.tags) ? job.tags.join(', ') : '',
          date_found: new Date().toISOString()
        }
      });
    }
  } catch (e) {}
}
return jobs.length > 0 ? jobs : [];

