const items = $input.all();
const rejectPatterns = [
  /\bus[\s-]?only\b/i, /\busa[\s-]?only\b/i, /\bunited[\s-]states[\s-]only\b/i,
  /\bcanada[\s-]?only\b/i, /\buk[\s-]?only\b/i, /\bunited[\s-]kingdom[\s-]?only\b/i,
  /\beu[\s-]?only\b/i, /\beurope[\s-]?only\b/i, /\baustralia[\s-]?only\b/i,
  /must be (based|located|residing|resident) in/i,
  /must live in/i,
  /must be authorized to work in/i,
  /authorized to work in the (us|usa|united states|uk|canada|eu|europe|australia)\b/i,
  /local work permit required/i,
  /work authorization required in/i,
  /\bonsite\b/i, /\bon-site\b/i,
  /\bhybrid\b/i,
  /office required/i,
  /in-office/i,
  /remote within .{1,40} only/i,
  /fixed us (business )?hours/i,
  /fixed eu (business )?hours/i,
  /fixed (est|pst|cet|cst|gmt) hours/i,
  /candidates? (must|should|need) (be )?(based|located|reside|live) in/i,
  /restricted to (us|usa|uk|canada|eu|europe|australia)/i
];
const filtered = [];
const rejectedList = [];
for (const item of items) {
  const j = item.json;
  const text = ((j.location_text || '') + ' ' + (j.description || '') + ' ' + (j.tags || '')).replace(/\s+/g, ' ');
  let rejected = false;
  let rejectReason = '';
  for (const pattern of rejectPatterns) {
    if (pattern.test(text)) {
      rejected = true;
      rejectReason = 'Hard filter: ' + pattern.source;
      break;
    }
  }
  if (rejected) {
    rejectedList.push({ json: { ...j, reject_reason: rejectReason, decision: 'reject', date_rejected: new Date().toISOString() } });
  } else {
    filtered.push({ json: { ...j } });
  }
}
// Store rejected for later sheet write — attach as metadata on passing items
// We use a workaround: pass rejected jobs through as special items with a flag
const allItems = [
  ...filtered,
  ...rejectedList.map(r => ({ json: { ...r.json, _hard_rejected: true } }))
];
return allItems;

const items = $input.all();
const results = [];
for (const item of items) {
  const aiResp = item.json;
  // Get the previous job data from the node that ran before AI check
  // In n8n split-batch flow, we need the original job data
  // The AI response wraps the original item
  let aiText = '';
  try {
    const content = (aiResp.content || [])[0];
    aiText = content ? (content.text || '') : '';
  } catch (e) {}
  let aiData = {};
  try {
    // Strip any markdown code fences if present
    const clean = aiText.replace(/```[a-z]*\n?/gi, '').replace(/```/g, '').trim();
    aiData = JSON.parse(clean);
  } catch (e) {
    aiData = { taiwan_eligible: 'unclear', reason: 'Parse error', location_risk: 'medium', timezone_risk: 'medium', contractor_possible: 'unclear', decision: 'manual_check' };
  }
  results.push({
    json: {
      ...item.json,
      taiwan_eligible: aiData.taiwan_eligible || 'unclear',
      taiwan_reason: aiData.reason || '',
      location_risk: aiData.location_risk || 'medium',
      timezone_risk: aiData.timezone_risk || 'medium',
      contractor_possible: aiData.contractor_possible || 'unclear',
      ai_decision: aiData.decision || 'manual_check'
    }
  });
}
return results;

const items = $input.all();
const asyncKeywords = [
  /\basync(hronous)?\b/i, /\bflexible hours\b/i, /\bflexible schedule\b/i,
  /\bdistributed team\b/i, /\bremote.?first\b/i, /\blow meeting\b/i,
  /\bwork across time zones?\b/i, /\bno meeting\b/i, /\bown your (hours|schedule|time)\b/i,
  /\bself.?directed\b/i, /\bself.?managed\b/i, /\bdeep work\b/i,
  /\binternational team\b/i, /\bfully distributed\b/i, /\bglobal team\b/i
];
const syncRejectPatterns = [
  /\bstrict 9.?to.?5\b/i,
  /\bfixed (us|est|pst|cet|cst|gmt) (business )?hours\b/i,
  /\bdaily live calls? required\b/i,
  /\bmust overlap full (us|est|pst|eu|uk) business day\b/i,
  /\brequired core hours.*\b(9|10) ?(am|a\.m).*\b(5|6) ?(pm|p\.m)\b/i
];
const results = [];
for (const item of items) {
  const j = item.json;
  const text = ((j.description || '') + ' ' + (j.tags || ''));
  let syncRisk = false;
  for (const p of syncRejectPatterns) {
    if (p.test(text)) { syncRisk = true; break; }
  }
  if (syncRisk) {
    results.push({ json: { ...j, async_level: 'sync_only', decision: 'reject', reject_reason: 'Sync-only work hours detected', date_rejected: new Date().toISOString() } });
    continue;
  }
  let asyncLevel = 'low';
  for (const p of asyncKeywords) {
    if (p.test(text)) { asyncLevel = 'high'; break; }
  }
  if (asyncLevel === 'low' && /\bflexible\b/i.test(text)) asyncLevel = 'medium';
  if (asyncLevel === 'low' && /\bremote\b/i.test(text)) asyncLevel = 'low';
  results.push({ json: { ...j, async_level: asyncLevel } });
}
return results;

const items = $input.all();
const results = [];
const primaryRoleTitles = ['data analyst', 'data scientist', 'junior data scientist', 'business intelligence analyst', 'bi analyst', 'marketing analyst', 'performance marketing analyst', 'growth analyst', 'ai marketing specialist', 'ai automation specialist', 'ai workflow consultant', 'creative strategist', 'martech analyst', 'marketing data analyst', 'digital analyst', 'growth hacker', 'analytics engineer'];
const primaryRoleDesc = ['data analyst', 'data scientist', 'business intelligence', 'marketing analyst', 'growth analyst', 'ai marketing', 'ai automation', 'martech', 'performance marketing', 'machine learning', 'data visualization', 'tableau', 'power bi', 'sql', 'python analytics'];
const adjacentRoles = ['analyst', 'marketing', 'data', 'ai', 'automation', 'researcher', 'strategist', 'insights'];
const rejectSync = ['sync_only'];
for (const item of items) {
  const j = item.json;
  if (j.async_level === 'sync_only' || j.taiwan_eligible === 'no' || j.location_risk === 'high') {
    results.push({ json: { ...j, score: 0, decision: 'reject', date_rejected: new Date().toISOString(), reject_reason: j.reject_reason || 'Failed post-AI filter' } });
    continue;
  }
  const titleLower = (j.job_title || '').toLowerCase();
  const descLower = (j.description || '').toLowerCase();
  const fullText = titleLower + ' ' + descLower;
  // Role score (0-25)
  let roleFitScore = 0;
  let roleCategory = 'other';
  for (const r of primaryRoleTitles) { if (titleLower.includes(r)) { roleFitScore = 25; roleCategory = r; break; } }
  if (!roleFitScore) { for (const r of primaryRoleDesc) { if (descLower.includes(r)) { roleFitScore = 20; roleCategory = r; break; } } }
  if (!roleFitScore) { for (const r of adjacentRoles) { if (titleLower.includes(r)) { roleFitScore = 15; roleCategory = 'adjacent (' + r + ')'; break; } } }
  // Taiwan score (0-40)
  let taiwanScore = 0;
  const locationText = (j.location_text || '' + j.description || '').toLowerCase();
  if (j.taiwan_eligible === 'yes') {
    if (/worldwide|work from anywhere|global remote|anywhere|international contractors?/.test(locationText)) taiwanScore = 40;
    else if (/apac/.test(locationText)) taiwanScore = 30;
    else if (j.location_risk === 'low') taiwanScore = 30;
    else taiwanScore = 20;
  } else if (j.taiwan_eligible === 'unclear') {
    taiwanScore = 20;
  }
  // Async score (0-25)
  let asyncScore = 0;
  if (j.async_level === 'high') asyncScore = 25;
  else if (j.async_level === 'medium') asyncScore = 20;
  else if (/distributed/i.test(fullText)) asyncScore = 15;
  else if (/remote.?first/i.test(fullText)) asyncScore = 10;
  else asyncScore = 5;
  // Salary score (0-25)
  let salaryScore = 0;
  const salaryText = (j.salary || '').toString();
  if (salaryText) {
    salaryScore = 10;
    const nums = salaryText.match(/[\d,]+/g);
    if (nums) {
      const maxAmt = Math.max(...nums.map(n => parseInt(n.replace(/,/g, ''), 10)));
      const monthly = maxAmt > 15000 ? Math.round(maxAmt / 12) : maxAmt;
      if (monthly >= 5000) salaryScore = 25;
      else if (monthly >= 3000) salaryScore = 15;
    }
  }
  const totalScore = taiwanScore + asyncScore + roleFitScore + salaryScore;
  // Why fit
  const whyFit = [];
  if (roleFitScore >= 20) whyFit.push('Title/description matches Jerry\'s ' + roleCategory + ' background');
  if (taiwanScore >= 30) whyFit.push('Open to global or worldwide remote workers');
  if (asyncScore >= 20) whyFit.push('Async-friendly culture — no fixed hours');
  if (salaryScore >= 15) whyFit.push('Salary above $3k/month listed');
  if (j.contractor_possible === 'yes') whyFit.push('Contractor/B2B engagement possible');
  // Final decision
  let decision;
  if (j.taiwan_eligible === 'no' || j.location_risk === 'high' || j.timezone_risk === 'high' || totalScore < 70) {
    decision = 'reject';
  } else if (totalScore >= 85 && j.taiwan_eligible === 'yes' && asyncScore >= 20 && j.location_risk === 'low') {
    decision = 'apply_immediately';
  } else if ((j.taiwan_eligible === 'unclear' || j.location_risk === 'medium') && totalScore >= 70) {
    decision = 'manual_check';
  } else {
    decision = 'save';
  }
  results.push({
    json: {
      ...j,
      score: totalScore,
      role_category: roleCategory,
      why_good_fit: whyFit.join('; '),
      decision: decision,
      taiwan_reason: j.taiwan_reason || '',
      application_status: 'new',
      notes: ''
    }
  });
}
return results;

