const items = $input.all();
const today = new Date().toLocaleDateString('en-US', { timeZone: 'Asia/Taipei', weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

const filtered = items.filter(i => i.json.score !== undefined && !i.json.date_rejected);
const rejected = items.filter(i => i.json.date_rejected);

const sorted = filtered.sort((a, b) => (Number(b.json.score) || 0) - (Number(a.json.score) || 0));
const topJobs = sorted.filter(i => (Number(i.json.score) || 0) >= 70);
const manualCheck = sorted.filter(i => i.json.decision === 'manual_check');
const applyNow = sorted.filter(i => i.json.decision === 'apply_immediately');

const rejectedByUS = rejected.filter(i => /us only|united states|usa only/i.test(i.json.reason || '')).length;
const rejectedByEU = rejected.filter(i => /eu only|europe only|uk only/i.test(i.json.reason || '')).length;
const rejectedByHybrid = rejected.filter(i => /hybrid|onsite|office/i.test(i.json.reason || '')).length;
const rejectedByTZ = rejected.filter(i => /sync.?only|fixed.*hours/i.test(i.json.reason || '')).length;

let subject = `[Jerry Jobs] ${applyNow.length} apply-now, ${manualCheck.length} manual check — ${today}`;
let body = `DAILY TAIWAN ELIGIBLE ASYNC REMOTE JOBS\n${today}\n${'='.repeat(50)}\n\n`;

if (applyNow.length > 0) {
  body += `APPLY IMMEDIATELY (${applyNow.length} job${applyNow.length > 1 ? 's' : ''})\n${'─'.repeat(40)}\n\n`;
  applyNow.forEach((item, i) => {
    const j = item.json;
    body += `${i + 1}. ${j.job_title}\n`;
    body += `   Company: ${j.company}\n`;
    body += `   Score: ${j.score}/100\n`;
    body += `   Taiwan eligible: ${j.taiwan_eligible}\n`;
    body += `   Reason: ${j.taiwan_reason || j.why_good_fit || 'See listing'}\n`;
    body += `   Async level: ${j.async_level}\n`;
    body += `   Timezone risk: ${j.timezone_risk}\n`;
    body += `   Salary: ${j.salary || 'Not listed'}\n`;
    body += `   Why it fits Jerry: ${j.why_good_fit || '—'}\n`;
    body += `   Apply: ${j.job_url}\n\n`;
  });
}

if (topJobs.filter(i => i.json.decision !== 'apply_immediately').length > 0) {
  const otherTop = topJobs.filter(i => i.json.decision !== 'apply_immediately');
  body += `\nTOP JOBS TODAY (${otherTop.length} more)\n${'─'.repeat(40)}\n\n`;
  otherTop.slice(0, 8).forEach((item, i) => {
    const j = item.json;
    body += `${i + 1}. ${j.job_title}\n`;
    body += `   Company: ${j.company}\n`;
    body += `   Score: ${j.score}/100\n`;
    body += `   Taiwan eligible: ${j.taiwan_eligible} | Async: ${j.async_level} | TZ risk: ${j.timezone_risk}\n`;
    body += `   Salary: ${j.salary || 'Not listed'}\n`;
    body += `   Why it fits: ${j.why_good_fit || '—'}\n`;
    body += `   Apply: ${j.job_url}\n\n`;
  });
}

if (manualCheck.length > 0) {
  body += `\nMANUAL CHECK REQUIRED (${manualCheck.length})\n${'─'.repeat(40)}\n`;
  body += `Taiwan eligibility is unclear but score is high. Review these yourself.\n\n`;
  manualCheck.forEach((item, i) => {
    const j = item.json;
    body += `${i + 1}. ${j.job_title} at ${j.company} (Score: ${j.score})\n`;
    body += `   ${j.taiwan_reason || 'Unclear location policy'}\n`;
    body += `   ${j.job_url}\n\n`;
  });
}

body += `\nREJECTED SUMMARY\n${'─'.repeat(40)}\n`;
body += `US only: ${rejectedByUS}\n`;
body += `EU/UK only: ${rejectedByEU}\n`;
body += `Hybrid / onsite: ${rejectedByHybrid}\n`;
body += `Fixed timezone: ${rejectedByTZ}\n`;
body += `Total rejected today: ${rejected.length}\n`;
body += `Total passing (score 70+): ${topJobs.length}\n`;

body += `\n${'='.repeat(50)}\nOne rule: I can do this job while living in Taiwan, without moving, without foreign work authorization, and without destroying my sleep schedule.\n`;

return [{ json: { subject, body, applyNowCount: applyNow.length, manualCheckCount: manualCheck.length, topCount: topJobs.length, rejectedCount: rejected.length } }];
